-- Seed support_kb_articles from contracts/support/v1/kb-catalog.json (kbVersion 2026-09-29).
-- Idempotent: existing (slug, locale) rows are left alone so admin edits survive a re-run.
begin;
insert into public.support_kb_articles (slug, locale, category, platforms, title, body, status, source, version, updated_by)
values ('product', 'en', 'product', array['ios','android','macos','windows','web']::text[], $kb$What Doppler VPN is$kb$, $kb$Doppler VPN is a VPN app by SIMNETIQ LTD, a UK company (No. 16861177, London). The only protocol is VLESS-Reality over Xray-core. It is built to work on networks that block or throttle ordinary VPNs. Users connect only through the official Doppler VPN apps. The apps set up servers after sign-in. There are no configuration files, no VPN links to copy, no QR codes, and no third-party clients (not v2rayNG, v2rayN, Streisand, V2Box, Hiddify, WireGuard, OpenVPN, Outline, or Shadowsocks). The Telegram bot does not hand out configs. Smart Route picks a server automatically; users can also pick one in the app. Server locations in the app include Canada (Toronto), Hong Kong, Russia (Moscow), Japan (Tokyo), Poland (Warsaw), Sweden (Stockholm), UAE (Dubai), and USA (Des Moines). The live list is in the app. A server in a country is not the customer's country of residence.$kb$, 'approved', $kb$knowledge/archive/en-2026-09-17.md$kb$, '2026-09-28', 'seed')
on conflict (slug, locale) do nothing;
insert into public.support_kb_articles (slug, locale, category, platforms, title, body, status, source, version, updated_by)
values ('downloads', 'en', 'downloads', array['ios','android','macos','windows']::text[], $kb$Platforms and downloads$kb$, $kb$iPhone, iPad, and Apple Silicon Mac use the App Store app: https://apps.apple.com/us/app/doppler-vpn-fast-secure/id6757091773. Android from Google Play: https://play.google.com/store/apps/details?id=org.dopplervpn.android. Android without Google Play uses the APK: https://www.dopplervpn.org/api/android/download/latest for most phones, and the same URL with ?abi=armeabi-v7a for older 32-bit phones. Android will ask to allow installs from that source. The APK has no Google Play billing; Pro for that install is bought on the website. Windows 10 (1809+) and Windows 11, 64-bit: https://www.dopplervpn.org/api/windows/download/latest-x64. The installer is not code-signed yet. If SmartScreen appears, choose More info, then Run anyway. Windows is a direct download, not a Microsoft Store purchase. All downloads are also on the Downloads page. Official installs are the Downloads page, or the matching platform page when the device is known: iPhone and iPad, Android, Mac, or Windows. A different address from the customer is not an official installer.$kb$, 'approved', $kb$knowledge/archive/en-2026-09-17.md$kb$, '2026-09-29', 'seed')
on conflict (slug, locale) do nothing;
insert into public.support_kb_articles (slug, locale, category, platforms, title, body, status, source, version, updated_by)
values ('account', 'en', 'account', array['ios','android','macos','windows','web']::text[], $kb$Anonymous Account ID and recovery$kb$, $kb$There is no email and password login and no Apple or Google login. Each account is an Account ID in the form VPN-XXXX-XXXX-XXXX. It is created on first launch of the app, or when subscribing on the website, and shown in Profile or Settings, then Account. The same Account ID signs the subscription in on another device. Treat it like a password. Support never asks for a card number, a wallet seed, or a private key. One account covers up to 10 devices. Devices can be viewed on the website account page; a device is removed in the app. An optional recovery contact (email or Telegram) is for recovery only. If the Account ID is lost and a contact was linked, Restore account on the Support page sends the ID to the linked email. If nothing was linked, the customer opens a support request. The Telegram language or the website language is not proof of where the customer lives. Delete account, in the app or on the delete-account page, deletes the whole account. It is not a way to remove only a support contact. An account with active paid access cannot be deleted until that access ends or is cancelled. Accounts without a subscription are deleted after 30 days of no subscription.$kb$, 'approved', $kb$knowledge/archive/en-2026-09-17.md$kb$, '2026-09-28', 'seed')
on conflict (slug, locale) do nothing;
insert into public.support_kb_articles (slug, locale, category, platforms, title, body, status, source, version, updated_by)
values ('where-to-buy', 'en', 'subscription', array['ios','android','macos','windows','web']::text[], $kb$Store subscriptions and one-time website access$kb$, $kb$Prices in USD before tax: monthly $6.99, 6 months $29.99, yearly $39.99. Pro includes the servers, Smart Route, Always-On VPN, up to 10 devices, and priority support. There is no free plan; a subscription is required to connect. App Store and Google Play sell auto-renewing subscriptions. New store customers get a 3-day free trial. The iPhone and Mac app shows monthly and yearly plans. The website sells one-time access for the period the customer chooses. It does not auto-renew and it does not keep a card for a later charge. Website card payments go through Revolut, including Apple Pay and Google Pay on that card checkout. Those wallets are not App Store or Google Play billing. Website crypto payments go through OxaPay (BTC, ETH, USDT TRC20/ERC20, USDC ERC20/Polygon). The website has no trial. Bonus days on the website are +7 on monthly, +14 on 6 months, and +30 on yearly. Promo codes do not apply to crypto payments. Windows and APK users buy on the website. There is no Telegram Stars purchase and no Microsoft Store purchase. Web card checkout is not offered in every country. The website checkout redirects EU member states away from payment. That redirect does not decide a customer's legal residence, and it does not apply to an older store purchase.$kb$, 'approved', $kb$knowledge/archive/en-2026-09-17.md$kb$, '2026-09-28', 'seed')
on conflict (slug, locale) do nothing;
insert into public.support_kb_articles (slug, locale, category, platforms, title, body, status, source, version, updated_by)
values ('cancel-and-restore', 'en', 'subscription', array['ios','android','macos','windows','web']::text[], $kb$Restore, cancel, and a missing subscription$kb$, $kb$Restore, cancel, and refund are different. Restore puts existing access back on an Account ID. Cancel stops a future store renewal. Refund asks for money back. App Store cancel: Settings, the person's name, Subscriptions, Doppler VPN, Cancel. Google Play cancel: Play Store, profile, Payments and subscriptions, Subscriptions, Cancel. Cancel at least 24 hours before the period ends. Access continues until the end of the paid period. A website purchase never renews, so there is nothing to cancel. App Store or Google Play restore: open the app, Profile, Subscription, Restore Purchases. One store subscription gives Pro to one Account ID at a time. Restoring on a different Account ID moves Pro to that account. Website purchase: the app must be signed in with the same Account ID used at checkout. Wait a few seconds and restart the app. On Windows, after paying on the website the app may say it has not detected the payment yet. Restart the app; the payment is not lost. The APK build has no Restore Purchases button because it has no Google Play billing.$kb$, 'approved', $kb$knowledge/archive/en-2026-09-17.md$kb$, '2026-09-28', 'seed')
on conflict (slug, locale) do nothing;
insert into public.support_kb_articles (slug, locale, category, platforms, title, body, status, source, version, updated_by)
values ('refund-requests', 'en', 'refund', array['ios','android','macos','windows','web']::text[], $kb$How to request a refund$kb$, $kb$Use the published statement, not a fee formula. EU/EEA and UK customers have a 14-day right to cancel. For other customers the published goodwill statement is a 30-day refund on the first purchase only, one per customer, and promotional or discounted purchases are excluded. Do not say that a processor fee, a crypto network fee, or a price change is deducted. Do not say that using the VPN once cancels the right to a refund. Do not promise that a bank, Apple, or Google will finish in a stated number of days. App Store purchases are requested from Apple, using Apple's refund instructions and reportaproblem.apple.com. Do not promise that Apple will approve it. Google Play purchases are requested in Google Play order history, under Google's refund policy. Do not promise that Google will approve it. Website card payments, including Apple Pay or Google Pay on the website, are refunded by Doppler on the card rail, not by the app store. Ask for the Account ID and the order reference. Never ask for the card number. Website crypto payments are OxaPay. Ask for the Account ID, the invoice reference, the coin, and the network. Never send a refund to an address you guessed. Ask the customer for the wallet address and confirm the asset, network, and amount before anyone sends it. There is no refund flow for Telegram Stars, the Microsoft Store, or a balance top-up, because those are not sales paths.$kb$, 'approved', $kb$Published August 2026 refund statement, fee sentences removed on 2026-09-28$kb$, '2026-09-28', 'seed')
on conflict (slug, locale) do nothing;
insert into public.support_kb_articles (slug, locale, category, platforms, title, body, status, source, version, updated_by)
values ('privacy', 'en', 'privacy', array['ios','android','macos','windows','web']::text[], $kb$Privacy$kb$, $kb$Doppler does not keep logs of browsing, visited sites, DNS queries, traffic volume, or VPN session activity. For security the account API keeps a sign-in record (IP address, Account ID, device ID, and time) for up to 90 days. Payment records are kept where the law requires it. A recovery or support contact is not the same thing as deleting the account. The full policy is the Privacy page.$kb$, 'approved', $kb$knowledge/archive/en-2026-09-17.md$kb$, '2026-09-28', 'seed')
on conflict (slug, locale) do nothing;
insert into public.support_kb_articles (slug, locale, category, platforms, title, body, status, source, version, updated_by)
values ('troubleshooting', 'en', 'connection', array['ios','android','macos','windows']::text[], $kb$Troubleshooting$kb$, $kb$If it will not connect: switch server, toggle the VPN off and on, restart the app, check that the subscription is active on this Account ID, and update the app. If it is slow: try Smart Route or a closer server, or switch between Wi-Fi and mobile data. If it drops: enable Always-On VPN. On Android, also allow the app to run in the background and disable battery optimization for Doppler. Turn Always-On off if the VPN is only needed occasionally and battery use is the problem. If the app says there is no subscription, check that the Account ID is the one that paid, then use Restore. If the App Store or Google Play cannot be opened in the customer's country, Android can use the APK. iPhone needs an App Store region where the app is available. The Mac app comes from the Mac App Store with the same link as iPhone. On Android the kill switch is Android Settings, Network, VPN, Doppler, Always-on VPN and Block connections without VPN. Windows has launch-at-startup, auto-connect, and a kill switch in Settings.$kb$, 'approved', $kb$knowledge/archive/en-2026-09-17.md$kb$, '2026-09-28', 'seed')
on conflict (slug, locale) do nothing;
insert into public.support_kb_articles (slug, locale, category, platforms, title, body, status, source, version, updated_by)
values ('contacts', 'en', 'support', array['ios','android','macos','windows','web']::text[], $kb$Contacts$kb$, $kb$Telegram support is this bot, @DopplerSupportBot. The Contact support button reaches a human. Email is support@simnetiq.com. The published wording says email is usually answered within 24 hours. That sentence is not a confirmed service-level agreement. News is posted on the news channel. The news channel is not a support queue. A written support reply is from the Doppler VPN team, not a named person.$kb$, 'approved', $kb$knowledge/archive/en-2026-09-17.md$kb$, '2026-09-29', 'seed')
on conflict (slug, locale) do nothing;
insert into public.support_kb_articles (slug, locale, category, platforms, title, body, status, source, version, updated_by)
values ('refund-kb-2026-09-17', 'en', 'refund', array['ios','android','macos','windows','web']::text[], $kb$Refunds (superseded 17 September 2026 knowledge file)$kb$, $kb$EU/EEA and UK customers: 14-day right to cancel (a proportional deduction may apply if the service was used). Everyone else: 30-day goodwill refund on the first purchase only, one per customer. Promotional or discounted purchases are excluded. App Store purchases: request at https://reportaproblem.apple.com. Google Play purchases: Google Play, Account, Order history. Website purchases (card or crypto): email support@simnetiq.com with the Account ID and order details. Card refunds take 5–10 business days; crypto refunds are sent back in the same coin (network fees and price changes are not covered).$kb$, 'retired', $kb$knowledge/archive/en-2026-09-17.md$kb$, '2026-09-17', 'seed')
on conflict (slug, locale) do nothing;
insert into public.support_kb_articles (slug, locale, category, platforms, title, body, status, source, version, updated_by)
values ('refund-policy-draft-2026-09-28', 'en', 'refund', array['web']::text[], $kb$Draft refund policy (not approved)$kb$, $kb$This draft is not an approved customer promise and must not be told to customers. Proposed default when a human approves a refund: return the gross amount paid. For a $6.99 charge with a $0.15 processor cost, the proposed customer amount is $6.99 and the $0.15 stays a merchant expense. Do not use $6.84. A regulation 36 or Article 14 use deduction is unresolved unless there is evidence of an express request for early performance. OxaPay merchant terms, asset, network, payout minimum, and any return fee are unresolved. Revolut acquiring-fee return is unresolved. The DMCC Act 2024 subscription rules were not in force on 28 September 2026. Checkout consent wording is not approved.$kb$, 'draft', $kb$contracts/refund/v1/refund-decision-matrix.json$kb$, '2026-09-28', 'seed')
on conflict (slug, locale) do nothing;
commit;
